from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[3];S=Path(__file__).resolve().parent
def write(p,v):p.write_bytes((json.dumps(v,ensure_ascii=False,indent=2)+'\n').encode('utf8'))
items=[]
for file in (S/'masters').glob('*-placement.json'):
    edge=file.name.split('-')[0];data=json.loads(file.read_text(encoding='utf8'))
    for item in data['instances']:
        kind=item['id'].split('-')[1];access=kind in ['upper','lower']
        collision=item.get('collision','Floor_'+edge+'_'+kind if access else 'none: distant water / support / decorative crown, not a playable surface')
        appearance={'depth':'dim blue/mauve distant water and recessed bone arches','spine':'continuous low-contrast porous bone/membrane support','step':'pale flat walking lip, one of three distinct tapered buttress silhouettes','crown':'irregular upward bone tendons with a natural upper silhouette'}.get(kind,'painted flat bone access lip joining existing room')
        items.append({**item,'runtime':'game/art/xumen-vertical/'+item['file'],'edge':edge,'count':1,'appearance':appearance,'judgement':'static','basis':'bone is rigid; distant painted anatomy stays static','material':'painted RGBA bitmap, no whole-terrain distortion','motion':'none','collision':collision,'interaction':'none: preserves original passage','sound':'existing chapter water bed; no new source','restore':'deterministic placement on reload','node':'AuthoredShafts/'+item['id'],'acceptance':'GPU bottom/middle/top plus no-front and original physical route','verified':'see game/progress.md; user aesthetic separate'})
    for i in range(2):
        for kind,count in [('FISH',6),('BUBBLE',6)]:
            items.append({'id':edge+'_'+kind+'_'+str(i),'edge':edge,'judgement':'motion','basis':'underwater ecology already present in approved concept','count':count,'layer':'middle water','method':'8-frame body plus path' if kind=='FISH' else 'prewarmed bounded pool with fade and recycle','alternative':'skeletal body' if kind=='FISH' else 'GPU particles','reason':'reuse measured stable technique; no new service cost','clock':'host.clock','collision':'none, decorative','interaction':'none','sound':'no new source, underwater distant decoration','restore':'seeded phase from chapter clock; pause freezes','node':'AuthoredShafts/'+edge+'_'+kind+'_'+str(i),'acceptance':'continuous browser playback, pause/resume and bounded instance QA'})
            axis,low,rise=(2123,103.847,785) if edge=='E33' else (3893,190.847,1102)
            items[-1]['bounds']=[axis+170,low-rise*(.35+.45*i),200,90] if kind=='FISH' else [axis+120+i*170,low-rise+40,55,rise-30]
            items[-1]['z']=-18 if kind=='FISH' else -5
            items[-1]['component']='ChapterFishGroup' if kind=='FISH' else 'EnvironmentBubbleEmitter'
    for kind,node in [('upper-world','Chunk_R1-06/ChapterEnvironment/World/Surface' if edge=='E33' else 'Chunk_R1-07/ChapterEnvironment/World/Surface'),('upper-middle','Chunk_R1-06/ChapterEnvironment/Middle/Surface' if edge=='E33' else 'Chunk_R1-07/ChapterEnvironment/Middle/Surface')]+([('e01-arch-top','Transition_E01/E01_MID_ARCH')] if edge=='E33' else [('lower-world','Chunk_R1-02/ChapterEnvironment/World/Surface'),('lower-middle','Chunk_R1-02/ChapterEnvironment/Middle/Surface'),('neighbor-world','Chunk_R1-06/ChapterEnvironment/World/Surface'),('neighbor-middle','Chunk_R1-06/ChapterEnvironment/Middle/Surface')]):
        items.append({'id':edge+'-CLEAN-'+kind,'judgement':'static','count':1,'runtime':'game/art/xumen-vertical/'+edge+'-'+kind+'.png','node':node,'purpose':'replace old baked water / cropped edge only; original layer preserved','motion':'inherits existing layer, no new animation','collision':'none: art replacement does not alter original bodies','interaction':'none','sound':'none: cleanup mask only','restore':'rebound by chunk_edges on every load','acceptance':'GPU no-front; adjacent route and E33 regression','ownership':'E33 upper replacements are production bases; E35 neighbor variants compose right cleanup on same left pixels and own final R1-06 nodes'})
write(S/'elements.json',{'elements':items,'policy':'original collision/abilities/7 rooms/V6 retained; no new gameplay','sourceHashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (S/'originals').glob('*.png')},'sourceTool':'built-in imagegen; model not exposed; generated task identity in PNG file provenance and prompts.json'})
